@js:args={}
baseUrl.match(/[^?=&]+=[^&]*/g).map(v=>{v=v.match(/(.+?)=(.*)/);if(v)args[v[1]]=v[2]})
host=args.h||''
bookid=args.bookid||''
cid=args.c||''

// 通过WebView获取章节密钥(复刻STV Flutter版流程)
key=java.getChapterKey(host,bookid)

// 获取登录Cookie
cCookie=''
c=source.getLoginHeaderMap()
if(c){cc=c.get('Cookie');if(cc)cCookie=cc}

// POST读取章节
readUrl=source.key+'/index.php?sajax=readchapter&h='+host+'&bookid='+bookid+'&c='+cid+'&key='+encodeURIComponent(key)
resp=java.post(readUrl,'',{'Cookie':cCookie,'referer':source.key+'/truyen/'+host+'/1/'+bookid+'/'+cid+'/','Content-type':'application/x-www-form-urlencoded'})
html=String(resp.body())
data=JSON.parse(html)
code=data.code
if(code=='0'||code=='1'){
  result=data.oridata||data.data||''
  result=result.replace(/\[banquyen=[^\]]+\]/g,'')
}else if(code=='7'){
  result='需要验证码'
}else if(code=='10002'){
  result='需要更新应用: '+(data.err||'')
}else{
  result='章节获取失败: '+(data.err||data.message||('code='+code))
}
